#ifndef SUNSTONE_NPU_BOARD_PRIVATE_H
#define SUNSTONE_NPU_BOARD_PRIVATE_H
#include "npu-board-session.h"
#include "client.h"
#include "npu_runtime.h"
#include "device_memory_pool.h"
#include "../board/application.h"
#define NPU_BOARD_SLOTS 1u
#define NPU_BOARD_MODELS 5u
#define NPU_BOARD_CORE 1u
#define NPU_BOARD_STACK 4096u
/* The linked catalogue, generated by apps/npu-board/catalogue.py. */
extern const struct npu_runtime_model npu_board_models[NPU_BOARD_MODELS];
struct npu_board_application {
    struct npu_board_session session;
    struct a733_npu_startup startup;
    struct npu_runtime runtime;
    struct npu_board_client client;
    struct device_memory_pool *pool;
    struct device_memory_lease lease;
    struct device_memory_extent extent;
    StaticTask_t tasks[2];
    StackType_t stacks[2][NPU_BOARD_STACK] __attribute__((aligned(16)));
    TaskHandle_t bootstrap,client_task;
    atomic_uint stopped;
};
extern struct npu_board_application npu_board;
int npu_board_irq_bind(struct npu_runtime *);
void board_usb0_task(void *);
int npu_board_thermal_start(void);
int npu_board_thermal_privileged(void (*)(void *),void *);
void npu_board_thermal_irq(void);
#endif
